// Validate + Normalize (Tailor CV)
// Mode: Run once for all items
// Language: JavaScript

function fail(code, message) {
  return [{
    json: {
      ok: false,
      blocksSchemaVersion: "1.0",
      contractError: { code, message },
      // Keep these for downstream nodes to pass through safely
      cvVersionId: null,
      cvTitle: "",
      summaryOfChanges: "",
      blocks: [],
      rewrittenCv: "",
      rewrittenCvLegacy: ""
    }
  }];
}

const root = $input.first().json || {};
const input = (root.body && typeof root.body === "object") ? root.body : root;

// Required fields
const cvVersionId = (input.cvVersionId === null || input.cvVersionId === undefined)
  ? null
  : String(input.cvVersionId);

const cvTitle = (input.cvTitle === null || input.cvTitle === undefined)
  ? ""
  : String(input.cvTitle);

const language = (input.language === "sv" || input.language === "en")
  ? input.language
  : null;

const blocksSchemaVersion = (input.blocksSchemaVersion === undefined || input.blocksSchemaVersion === null)
  ? "1.0"
  : String(input.blocksSchemaVersion);

const jobContextSchemaVersion = (input.jobContextSchemaVersion === undefined || input.jobContextSchemaVersion === null)
  ? null
  : String(input.jobContextSchemaVersion);

const blocks = input.blocks;
const jobContext = input.jobContext;

// Validate schema versions
if (blocksSchemaVersion !== "1.0") {
  return fail("INVALID_BLOCKS_SCHEMA_VERSION", "blocksSchemaVersion must be '1.0'");
}
if (jobContextSchemaVersion !== "1.0") {
  return fail("INVALID_JOBCONTEXT_SCHEMA_VERSION", "jobContextSchemaVersion must be '1.0'");
}

// Validate language
if (!language) {
  return fail("INVALID_LANGUAGE", "language must be 'sv' or 'en'");
}

// Validate blocks
if (!Array.isArray(blocks) || blocks.length === 0) {
  return fail("INVALID_BLOCKS", "blocks must be a non-empty array");
}

// Minimal per-block validation (don’t overfit, but catch the dangerous stuff)
for (let i = 0; i < blocks.length; i++) {
  const b = blocks[i];
  if (!b || typeof b !== "object") return fail("INVALID_BLOCK", "Each block must be an object");

  const blockId = (b.blockId === undefined || b.blockId === null) ? "" : String(b.blockId).trim();
  const type = (b.type === undefined || b.type === null) ? "" : String(b.type).trim();
  const hasOrder = (typeof b.order === "number" && Number.isFinite(b.order));
  const textOk = (b.text === undefined || b.text === null || typeof b.text === "string");

  if (!blockId) return fail("INVALID_BLOCK_ID", "Each block must have non-empty blockId");
  if (!type) return fail("INVALID_BLOCK_TYPE", "Each block must have non-empty type");
  if (!hasOrder) return fail("INVALID_BLOCK_ORDER", "Each block must have numeric order");
  if (!textOk) return fail("INVALID_BLOCK_TEXT", "Each block must have text as string (or empty)");
}

// Tailor REQUIRES jobContext
if (!jobContext || typeof jobContext !== "object") {
  return fail("MISSING_JOB_CONTEXT", "Tailoring requires jobContext");
}

// Optional targetRole
const targetRole = (input.targetRole === undefined || input.targetRole === null)
  ? ""
  : String(input.targetRole);

// Output normalized payload for downstream nodes
return [{
  json: {
    ok: true,
    cvVersionId,
    cvTitle,
    language,
    targetRole,
    blocksSchemaVersion: "1.0",
    blocks,
    jobContextSchemaVersion: "1.0",
    jobContext
  }
}];

// Build Tailor (Tailor CV)
// Mode: Run once for all items
// Language: JavaScript

const input = $input.first().json || {};

// Preserve upstream ok-state (never "fix" upstream errors here)
const ok = input.ok === true;

// Hard default language guard
const language = (input.language === "sv" || input.language === "en") ? input.language : "en";

// Always preserve these (pass-through)
const cvVersionId = (typeof input.cvVersionId === "string") ? input.cvVersionId : null;
const cvTitle = (typeof input.cvTitle === "string") ? input.cvTitle : "";
const targetRole = (typeof input.targetRole === "string") ? input.targetRole : "";
const blocksSchemaVersion = (typeof input.blocksSchemaVersion === "string") ? input.blocksSchemaVersion : "1.0";
const jobContextSchemaVersion = (typeof input.jobContextSchemaVersion === "string") ? input.jobContextSchemaVersion : "1.0";

// CRITICAL: preserve blocks for downstream deterministic apply
const blocks = Array.isArray(input.blocks) ? input.blocks : [];

// Preserve jobContext (optional but expected)
const jobContext = (input.jobContext && typeof input.jobContext === "object" && !Array.isArray(input.jobContext))
  ? input.jobContext
  : null;

const system = `
You are operating inside Drafted, a deterministic block-based CV system.

Hard rules (non-negotiable):
- Do NOT add, remove, merge, split, or reorder blocks.
- Do NOT modify blockId, type, label, or order.
- Do NOT change employer/title/dates/institution/degree/program fields.
- You may ONLY rephrase or reprioritize existing text.
- Do NOT invent new responsibilities, projects, claims, metrics, tools, or achievements.
- Do NOT introduce new capabilities (risk management, financial tracking, delivery governance, customer interface, etc.) unless they are already explicitly stated in that block.

Bullet integrity rules:
- Do NOT add new bullet points.
- Do NOT increase the number of bullets in any block.
- Do NOT create new responsibilities that were not already present.
- You may only rewrite or emphasize what already exists in that block’s text.

Positioning rule:
- You may adjust tone and emphasis to better match the job context.
- You may not fabricate experience to fill gaps.

Language rule:
- Keep output language exactly: ${language}.

Output must be STRICT JSON ONLY:

{
  "edits": [
    { "blockId": "string", "text": "string" }
  ],
  "summaryOfChanges": "string"
}

Only include blocks that genuinely need rewriting.
If no safe alignment is possible: return {"edits":[],"summaryOfChanges":""}.
`.trim();

let user;

if (!ok) {
  user = `Return exactly: {"edits":[],"summaryOfChanges":""}`;
} else if (!jobContext) {
  // If jobContext is missing, do nothing. No guessing.
  user = `No jobContext was provided. Return exactly: {"edits":[],"summaryOfChanges":""}`;
} else if (!Array.isArray(blocks) || blocks.length === 0) {
  // If blocks missing, do nothing. No hallucination.
  user = `No CV blocks were provided. Return exactly: {"edits":[],"summaryOfChanges":""}`;
} else {
  user = `
Tailor the CV to the provided job context.

JobContext (schema ${jobContextSchemaVersion}):
${JSON.stringify(jobContext, null, 2)}

Optional target role text (may be empty):
${targetRole ? JSON.stringify(targetRole) : '""'}

CV blocks (schema ${blocksSchemaVersion}):
${JSON.stringify(blocks, null, 2)}

Remember:
- No structure changes.
- No identity inflation.
- Return JSON only.
`.trim();
}

// IMPORTANT: return llmMessages + pass-through fields INCLUDING blocks + jobContext
return [
  {
    json: {
      llmMessages: [
        { role: "system", content: system },
        { role: "user", content: user }
      ],
      ok,
      cvVersionId,
      cvTitle,
      language,
      targetRole,
      blocksSchemaVersion,
      blocks,
      jobContextSchemaVersion,
      jobContext
    }
  }
];

// Normalize Output (Tailor CV)
// Mode: Run once for all items
// Language: JavaScript

function fail(code, message, rawText) {
  return [{
    json: {
      ok: false,
      blocksSchemaVersion: "1.0",
      contractError: { code, message },
      rawText: rawText || ""
    }
  }];
}

const input = $input.first().json || {};

// 1) Find raw model text
let raw = null;

// Most common for your node (seen in screenshot)
raw = input?.output?.[0]?.content?.[0]?.text ?? null;

// Fallbacks
if (!raw && typeof input?.output?.[0]?.content?.[0]?.output_text === "string") raw = input.output[0].content[0].output_text;
if (!raw && typeof input?.text === "string") raw = input.text;
if (!raw && typeof input?.response === "string") raw = input.response;

if (!raw || typeof raw !== "string") {
  return fail("MISSING_MODEL_OUTPUT", "Could not find model output text to parse");
}

// 2) Parse JSON (trim once)
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  try {
    parsed = JSON.parse(raw.trim());
  } catch (e2) {
    return fail("MODEL_OUTPUT_NOT_JSON", "Model output was not valid JSON", raw);
  }
}

// 3) Validate
if (!Array.isArray(parsed.edits)) {
  return fail("INVALID_MODEL_OUTPUT", "Model JSON must contain edits[] array", raw);
}
if (typeof parsed.summaryOfChanges !== "string") {
  return fail("INVALID_MODEL_OUTPUT", "Model JSON must contain summaryOfChanges string", raw);
}

// 4) Minimal validation of edits
for (let i = 0; i < parsed.edits.length; i++) {
  const e = parsed.edits[i];
  if (!e || typeof e !== "object") return fail("INVALID_EDIT", "Each edit must be an object", raw);
  const blockId = (e.blockId == null) ? "" : String(e.blockId).trim();
  if (!blockId) return fail("INVALID_EDIT", "Each edit must have non-empty blockId", raw);
  if (e.text != null && typeof e.text !== "string") return fail("INVALID_EDIT", "Edit.text must be a string", raw);
}

// 5) Output normalized (keep original output for debugging)
return [{
  json: {
    ...input,
    edits: parsed.edits,
    summaryOfChanges: parsed.summaryOfChanges
  }
}];

// Deterministic Apply + Canonicalize (Tailor CV)
// Mode: Run once for all items
// Language: JavaScript

function fail(code, message, input) {
  return [{
    json: {
      ok: false,
      blocksSchemaVersion: "1.0",
      contractError: { code, message },
      cvVersionId: input.cvVersionId ?? null,
      cvTitle: input.cvTitle ?? "",
      summaryOfChanges: "",
      blocks: input.blocks ?? [],
      rewrittenCv: "",
      rewrittenCvLegacy: ""
    }
  }];
}

function safeString(v) {
  if (v === null || v === undefined) return "";
  return String(v);
}

function normalizeNewlines(s) {
  return safeString(s).replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
}

function buildRewrittenCvFromBlocks(blocks) {
  // Deterministic, minimal: each block text separated by blank line.
  // blocks[] remains canonical; rewrittenCv is derived.
  const parts = [];
  for (const b of blocks) {
    const t = normalizeNewlines(b.text || "");
    if (t) parts.push(t);
  }
  return parts.join("\n\n").trim();
}

function makeTailorCvVersionId(prev) {
  // Deterministic-ish without libs: prev + timestamp if prev exists else timestamp only.
  // This is acceptable because cvVersionId is allowed to change each run.
  const ts = Date.now();
  if (prev && typeof prev === "string" && prev.trim()) return `${prev.trim()}_tailor_${ts}`;
  return `tailor_${ts}`;
}

const input = $input.first().json || {};

// Pass-through failures
if (input.ok !== true) {
  return [{ json: input }];
}

// Validate required fields
if (input.blocksSchemaVersion !== "1.0") {
  return fail("INVALID_BLOCKS_SCHEMA_VERSION", "blocksSchemaVersion must be '1.0'", input);
}
if (!Array.isArray(input.blocks) || input.blocks.length === 0) {
  return fail("INVALID_BLOCKS", "blocks must be a non-empty array", input);
}
if (!Array.isArray(input.edits)) {
  return fail("INVALID_EDITS", "edits must be an array", input);
}

// Build edit map (blockId -> text)
const editMap = new Map();
for (const e of input.edits) {
  if (!e || typeof e !== "object") continue;
  const id = safeString(e.blockId).trim();
  if (!id) continue;
  // Only accept text edits; if missing text, treat as no-op
  if (e.text === undefined || e.text === null) continue;
  editMap.set(id, safeString(e.text));
}

// Apply edits deterministically
const nextBlocks = input.blocks.map((b) => {
  // Defensive clone shallow
  const nb = { ...b };

  const id = safeString(nb.blockId).trim();
  if (id && editMap.has(id)) {
    // Only update text
    nb.text = normalizeNewlines(editMap.get(id));
  }

  return nb;
});

// Canonical sort by order asc, stable tie-breaker by blockId
nextBlocks.sort((a, b) => {
  const oa = (typeof a.order === "number" ? a.order : 0);
  const ob = (typeof b.order === "number" ? b.order : 0);
  if (oa !== ob) return oa - ob;
  const ida = safeString(a.blockId);
  const idb = safeString(b.blockId);
  return ida.localeCompare(idb);
});

// summaryOfChanges clamp
let summary = safeString(input.summaryOfChanges).trim();
if (summary.length > 1200) summary = summary.slice(0, 1200).trim();

// Derived fields
const rewrittenCv = buildRewrittenCvFromBlocks(nextBlocks);

// Produce next payload for BuildResponse
return [{
  json: {
    ok: true,
    blocksSchemaVersion: "1.0",
    cvVersionId: makeTailorCvVersionId(input.cvVersionId),
    cvTitle: safeString(input.cvTitle).trim(),
    summaryOfChanges: summary,
    blocks: nextBlocks,
    rewrittenCv,
    rewrittenCvLegacy: rewrittenCv
  }
}];

// BuildResponse (Tailor CV)
// Mode: Run once for all items
// Language: JavaScript

const input = $input.first().json || {};

// If already failed upstream, return as-is but enforce schema shape
if (input.ok !== true) {
  return [{
    json: {
      ok: false,
      blocksSchemaVersion: "1.0",
      contractError: input.contractError || {
        code: "UNKNOWN_ERROR",
        message: "Tailor failed"
      },
      cvVersionId: input.cvVersionId ?? null,
      cvTitle: input.cvTitle ?? "",
      summaryOfChanges: "",
      blocks: input.blocks ?? [],
      rewrittenCv: "",
      rewrittenCvLegacy: ""
    }
  }];
}

// Success path — emit ONLY contract fields
return [{
  json: {
    ok: true,
    blocksSchemaVersion: "1.0",
    cvVersionId: input.cvVersionId,
    cvTitle: input.cvTitle,
    summaryOfChanges: input.summaryOfChanges || "",
    blocks: input.blocks,
    rewrittenCv: input.rewrittenCv,
    rewrittenCvLegacy: input.rewrittenCvLegacy
  }
}];

/**
 * Tailor Guard (Drafted)
 *
 * Input (expected on $input.first().json):
 * - ok: boolean
 * - language: "en" | "sv" (optional, default "en")
 * - blocksSchemaVersion: "1.0"
 * - blocks: non-empty array (CV blocks)
 * - edits: array from Normalize Output: [{ blockId, text }]
 * - summaryOfChanges: string
 *
 * Output:
 * - Same object, but with edits sanitized/dropped if unsafe.
 * - Never throws. If input invalid, forces edits=[] and summaryOfChanges="".
 *
 * Strategy:
 * - Only allow edits for existing blockIds.
 * - For experience blocks: forbid bullet-count increase.
 * - For all blocks: forbid introducing certain "inflation phrases" unless they already existed in the original block text.
 * - Enforce output language roughly (block Swedish leakage when language is en).
 * - Clamp sizes and strip leading garbage.
 */

const input = ($input.first() && $input.first().json) ? $input.first().json : {};

function safeString(x) {
  return (typeof x === "string") ? x : (x == null ? "" : String(x));
}

function isPlainObject(x) {
  return !!x && typeof x === "object" && !Array.isArray(x);
}

function sanitizeLeadingGarbage(str) {
  return safeString(str).replace(/^\uFEFF/, "").replace(/^=+/, "").trim();
}

function normLite(s) {
  return safeString(s).toLowerCase().replace(/\s+/g, " ").trim();
}

function splitLines(s) {
  return safeString(s).replace(/\r/g, "").split("\n");
}

function countBullets(text) {
  const lines = splitLines(text);
  let n = 0;
  for (const line of lines) {
    const t = line.trim();
    if (!t) continue;
    // Common bullet styles: •, -, *, –
    if (/^(•|\-|\*|–)\s+/.test(t)) n += 1;
  }
  return n;
}

function looksSwedish(text) {
  const t = safeString(text);
  if (/[åäöÅÄÖ]/.test(t)) return true;
  const low = t.toLowerCase();
  // very rough Swedish leakage signals
  const hits = [
    " och ", " att ", " som ", " för ", " med ", " inte ", " även ", " på ", " är ", " det ", " den ", " detta "
  ].filter(w => low.includes(w)).length;
  return hits >= 2;
}

const language = (input.language === "sv" || input.language === "en") ? input.language : "en";

// Validate blocks
const blocks = Array.isArray(input.blocks) ? input.blocks : [];
if (input.ok !== true || input.blocksSchemaVersion !== "1.0" || blocks.length === 0) {
  // Force safe no-op
  const out = {
    ...input,
    edits: [],
    summaryOfChanges: ""
  };
  return [{ json: out }];
}

// Build lookup
const byId = new Map();
for (const b of blocks) {
  if (!isPlainObject(b)) continue;
  const id = safeString(b.blockId).trim();
  if (!id) continue;
  byId.set(id, b);
}

// Inflation phrases that often get hallucinated in tailoring.
// Allowed only if already present in the original block text (same block).
const INFLATION_PHRASES = [
  "risk management",
  "delivery governance",
  "financial tracking",
  "financial control",
  "budget control",
  "predictable performance",
  "predictable prioritisation",
  "customer interface",
  "primary customer interface",
  "security clearance",
  "defence",
  "defense",
  "high-volume environments",
  "structured reporting",
  "escalation",
  "delivery risk",
];

// Hard cap to prevent runaway text
const MAX_TEXT_LEN = 1800;
const MAX_SUMMARY_LEN = 1200;

const editsIn = Array.isArray(input.edits) ? input.edits : [];
const safeEdits = [];
const dropped = []; // internal log; we do not include this in output unless you want

for (const e of editsIn) {
  if (!isPlainObject(e)) continue;

  const blockId = safeString(e.blockId).trim();
  let nextText = sanitizeLeadingGarbage(e.text);

  if (!blockId || !byId.has(blockId)) {
    dropped.push({ blockId, reason: "UNKNOWN_BLOCK" });
    continue;
  }

  const block = byId.get(blockId);
  const type = safeString(block.type).trim();
  const prevText = safeString(block.text);

  // Empty text edits are allowed but pointless. Keep only if you explicitly want to support clearing.
  if (!nextText) {
    dropped.push({ blockId, reason: "EMPTY_TEXT" });
    continue;
  }

  // Clamp
  if (nextText.length > MAX_TEXT_LEN) nextText = nextText.slice(0, MAX_TEXT_LEN).trim();

  // Language guard: if CV language is en, reject Swedish leakage
  if (language === "en" && looksSwedish(nextText)) {
    dropped.push({ blockId, reason: "LANGUAGE_LEAK_SV" });
    continue;
  }

  // Experience bullet guard: do not increase bullet count
  if (type === "experience") {
    const prevBullets = countBullets(prevText);
    const nextBullets = countBullets(nextText);

    // If original had bullets, new must not add more
    if (prevBullets > 0 && nextBullets > prevBullets) {
      dropped.push({ blockId, reason: "BULLET_COUNT_INCREASE", prevBullets, nextBullets });
      continue;
    }

    // If original had bullets but new has none, reject (usually means model rewrote into prose)
    if (prevBullets > 0 && nextBullets === 0) {
      dropped.push({ blockId, reason: "BULLETS_REMOVED", prevBullets, nextBullets });
      continue;
    }
  }

  // Inflation phrase guard: if new text adds any inflation phrase not present before, reject
  const prevNorm = normLite(prevText);
  const nextNorm = normLite(nextText);

  let inflationHit = null;
  for (const p of INFLATION_PHRASES) {
    const pn = normLite(p);
    const hadBefore = prevNorm.includes(pn);
    const hasNow = nextNorm.includes(pn);
    if (!hadBefore && hasNow) {
      inflationHit = p;
      break;
    }
  }
  if (inflationHit) {
    dropped.push({ blockId, reason: "INFLATION_PHRASE_ADDED", phrase: inflationHit });
    continue;
  }

  // If the edit is identical after trimming, drop it (no-op)
  if (nextNorm === prevNorm) {
    dropped.push({ blockId, reason: "NO_OP" });
    continue;
  }

  safeEdits.push({ blockId, text: nextText });
}

// Summary clamp
let summary = sanitizeLeadingGarbage(input.summaryOfChanges);
if (summary.length > MAX_SUMMARY_LEN) summary = summary.slice(0, MAX_SUMMARY_LEN).trim();

// If all edits dropped, force summary empty to avoid misleading “changes made”
if (safeEdits.length === 0) summary = "";

// IMPORTANT: Do not change blocks here. Only sanitize edits.
// Deterministic Apply node will apply safely.
const out = {
  ...input,
  edits: safeEdits,
  summaryOfChanges: summary
};

return [{ json: out }];
